393  // local printOperand, without updating public operands
   394  static void _printOperand(MCInst *MI, unsigned OpNo, SStream *O)
   395  {
   396          MCOperand *Op  = MCInst_getOperand(MI, OpNo);
   397          if (MCOperand_isReg(Op)) {
   398                  printRegName(O, MCOperand_getReg(Op));
   399          } else if (MCOperand_isImm(Op)) {
   400                  int64_t imm = MCOperand_getImm(Op);
   401                  printImm(MI, O, imm, MI->csh->imm_unsigned);
   402          }
   403  }
