   432  static void printSrcIdx(MCInst *MI, unsigned Op, SStream *O)
   433  {
   434          MCOperand *SegReg;
   435          int reg;
   436
   437          if (MI->csh->detail) {
   438  #ifndef CAPSTONE_DIET
   439                  uint8_t access[6];
   440  #endif
   441
   442                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_MEM;
   443                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->x86opsize;
   444                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.segment = X86_REG_INVALID;
   445                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.base = X86_REG_INVALID;
   446                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.index = X86_REG_INVALID;
   447                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.scale = 1;
   448                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.disp = 0;
   449
   450  #ifndef CAPSTONE_DIET
   451                  get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
   452                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].access = access[MI->flat_insn->detail->x86.op_count];
   453  #endif
   454          }
   455
   456          SegReg = MCInst_getOperand(MI, Op + 1);
   457          reg = MCOperand_getReg(SegReg);
   458
   459          // If this has a segment register, print it.
   460          if (reg) {
   461                  _printOperand(MI, Op + 1, O);
   462                  if (MI->csh->detail) {
   463                          MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.segment = X86_register_map(reg);
   464                  }
   465                  SStream_concat0(O, ":");
   466          }
   467
   468          SStream_concat0(O, "[");
   469          set_mem_access(MI, true);
   470          printOperand(MI, Op, O);
